import java.io.*;
import java.util.*;
import java.util.concurrent.TimeUnit;
import java.util.regex.Pattern;

public class Main {
    private static final int MAX_COMMAND_LENGTH = 2048;
    private static final long EXECUTION_TIMEOUT_SECONDS = 5;
    private static final Set<String> ALLOWED_COMMANDS = new HashSet<>(Arrays.asList("echo", "ls", "pwd", "whoami", "date", "uptime", "hostname", "uname", "id"));
    private static final Pattern SAFE_TOKEN = Pattern.compile("[A-Za-z0-9._/-]+");
    private static final Pattern FORBIDDEN = Pattern.compile("[;&|<>$`(){}\\[\\]*?!~#\"'\\n\\r]");

    public static class CommandResult {
        public final boolean success;
        public final int exitCode;
        public final String output;
        public CommandResult(boolean success, int exitCode, String output) {...}
    }

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String command = readCommand(reader);
            CommandResult result = validateAndExecute(command);
            System.out.print(result.output);
            if (!result.success) { System.out.println("Command failed with exit code " + result.exitCode); }
        } catch (Exception e) { System.out.println("Error: " + e.getMessage()); }
    }

    public static String readCommand(BufferedReader reader) throws IOException { return reader.readLine(); }

    public static CommandResult validateAndExecute(String command) {
        String validationError = validateCommand(command);
        if (validationError != null) return new CommandResult(false, -1, "Validation error: " + validationError);
        try { return executeCommand(command); } catch (Exception e) { return new CommandResult(false, -1, "Execution error: " + e.getMessage()); }
    }

    public static String validateCommand(String command) {
        if (command == null) return "Command cannot be null.";
        if (command.trim().isEmpty()) return "Command cannot be empty.";
        if (command.length() > MAX_COMMAND_LENGTH) return "Command too long.";
        if (command.indexOf('\0') >= 0) return "Command contains null byte.";
        if (FORBIDDEN.matcher(command).find()) return "Command contains forbidden shell metacharacters.";
        String[] tokens = command.trim().split("\\s+");
        if (tokens.length == 0) return "Command cannot be empty.";
        if (!ALLOWED_COMMANDS.contains(tokens[0])) return "Command not allowed: " + tokens[0];
        for (int i=1; i<tokens.length; i++) { if (!SAFE_TOKEN.matcher(tokens[i]).matches()) return "Unsafe argument: " + tokens[i]; }
        return null;
    }

    public static CommandResult executeCommand(String command) throws IOException, InterruptedException {
        ProcessBuilder pb = new ProcessBuilder("/bin/bash", "-c", command);
        pb.redirectErrorStream(true);
        Process process = pb.start();
        StringBuilder output = new StringBuilder();
        try (BufferedReader br = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
            String line;
            while ((line = br.readLine()) != null) { output.append(line).append(System.lineSeparator()); }
        }
        boolean finished = process.waitFor(EXECUTION_TIMEOUT_SECONDS, TimeUnit.SECONDS);
        if (!finished) { process.destroyForcibly(); return new CommandResult(false, -1, "Command timed out."); }
        int exitCode = process.exitValue();
        return new CommandResult(exitCode == 0, exitCode, output.toString());
    }
}

